        key = text[i:j].strip()
        if j >= n or text[j] == SEP:
            if key:
                raise ValueError(f"field without '=': {text[i:j]!r}")
            i = j + 1
            continue
        if not key:
            raise ValueError("empty key")
        j += 1  # skip '='
        while j < n and text[j].isspace():
            j += 1
        if j < n and text[j] == QUOTE:
            j += 1
            value = ""
            while True:
                if j >= n:
                    raise ValueError("unterminated quote")
                if text[j] == QUOTE:
                    if j + 1 < n and text[j + 1] == QUOTE:
                        value += QUOTE
                        j += 2
                        continue
                    j += 1
                    break
                value += text[j]
                j += 1
            while j < n and text[j] != SEP:
                if not text[j].isspace():
                    raise ValueError("text after closing quote")
                j += 1
